import{_ as t,o as d,c as a,a3 as o}from"./chunks/framework.B8xISX-C.js";const f=JSON.parse('{"title":"shields","description":"","frontmatter":{},"headers":[],"relativePath":"reference/shields.md","filePath":"reference/shields.md"}'),s={name:"reference/shields.md"};function c(r,e,i,n,l,h){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="shields" tabindex="-1">shields <a class="header-anchor" href="#shields" aria-label="Permalink to &quot;shields&quot;">​</a></h1><p>A shield tier, unlocked by an application (<code>app</code>). <code>space</code> and <code>cost</code> list one value per hull size.</p><p>A mod adds records in <code>records/shields/&lt;file&gt;.json</code> (<code>{ &quot;$schema&quot;: &quot;carina-records/1&quot;, &quot;catalog&quot;: &quot;shields&quot;, &quot;records&quot;: [...] }</code>) and changes base records with patch rows on catalog <code>shields</code>. Schema: <a href="/carina-mod-template/schemas/records/shields.schema.json">shields records schema</a>.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><p>A mod record leaves out <code>id</code> and <code>prov</code>: the game assigns ids, and <code>prov</code> is the project&#39;s own provenance.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><span id="f-key" class="field-name"><code>key</code></span><a class="field-link" href="#f-key" aria-label="Link to key">#</a></td><td><code>&lt;namespace&gt;.&lt;snake_case&gt;</code>: your package id with <code>-</code> read as <code>_</code>, then a name</td><td>yes</td><td></td></tr><tr><td><span id="f-app" class="field-name"><code>app</code></span><a class="field-link" href="#f-app" aria-label="Link to app">#</a></td><td>snake_case key</td><td>yes</td><td></td></tr><tr><td><span id="f-reduction" class="field-name"><code>reduction</code></span><a class="field-link" href="#f-reduction" aria-label="Link to reduction">#</a></td><td>integer &gt;= 1</td><td>yes</td><td></td></tr><tr><td><span id="f-space" class="field-name"><code>space</code></span><a class="field-link" href="#f-space" aria-label="Link to space">#</a></td><td>[integer &gt;= 0, integer &gt;= 0, integer &gt;= 0, integer &gt;= 0, integer &gt;= 0, integer &gt;= 0]</td><td>yes</td><td>one per hull size, in order: <code>frigate</code>, <code>destroyer</code>, <code>cruiser</code>, <code>battleship</code>, <code>titan</code>, <code>colossus</code></td></tr><tr><td><span id="f-cost" class="field-name"><code>cost</code></span><a class="field-link" href="#f-cost" aria-label="Link to cost">#</a></td><td>[integer &gt;= 0, integer &gt;= 0, integer &gt;= 0, integer &gt;= 0, integer &gt;= 0, integer &gt;= 0]</td><td>yes</td><td>one per hull size, in order: <code>frigate</code>, <code>destroyer</code>, <code>cruiser</code>, <code>battleship</code>, <code>titan</code>, <code>colossus</code></td></tr><tr><td><span id="f-nameKey" class="field-name"><code>nameKey</code></span><a class="field-link" href="#f-nameKey" aria-label="Link to nameKey">#</a></td><td>text key</td><td>yes</td><td></td></tr></tbody></table><h2 id="also-register-it-in" tabindex="-1">Also register it in <a class="header-anchor" href="#also-register-it-in" aria-label="Permalink to &quot;Also register it in&quot;">​</a></h2><p>Nothing else: the record works on its own.</p><h2 id="computer-players" tabindex="-1">Computer players <a class="header-anchor" href="#computer-players" aria-label="Permalink to &quot;Computer players&quot;">​</a></h2><p>The ship designer, starting designs and refits take the strongest known shield by its stats: <code>reduction</code>, then the later record on a full tie. A weaker mod tier is never picked over a stronger one the empire knows.</p><h2 id="patch-paths" tabindex="-1">Patch paths <a class="header-anchor" href="#patch-paths" aria-label="Permalink to &quot;Patch paths&quot;">​</a></h2><p>Rows on this catalog address a record by <code>key</code> and a field by <code>path</code>:</p><ul><li><code>set</code>: <code>app</code>, <code>cost</code>, <code>nameKey</code>, <code>reduction</code>, <code>space</code></li><li><code>append</code>, <code>insertAfter</code>, <code>removeValue</code>: none (no list fields)</li></ul>',13)])])}const u=t(s,[["render",c]]);export{f as __pageData,u as default};
